#include <iostream>
#include <utility>

class Locker {
public:
    explicit Locker(int item) : item_{new int{item}} {}
    Locker(Locker&& other) noexcept : item_{other.item_} { other.item_ = nullptr; }
    Locker& operator=(Locker&& other) noexcept {
        if (this != &other) {
            delete item_;
            item_ = other.item_;
            other.item_ = nullptr;
        }
        return *this;
    }
    ~Locker() { delete item_; }
    bool empty() const { return item_ == nullptr; }
    int item() const { return *item_; }
private:
    int* item_;
};

int main() {
    Locker a{5};
    Locker b{9};
    b = std::move(a);
    std::cout << "b holds " << b.item() << ", a is " << (a.empty() ? "empty" : "full") << '\n';
}

