#include <iostream>
#include <string>
#include <utility>

std::string last;                       // what the last statement called

struct Truck {
    Truck() = default;
    Truck(const Truck&) { last = "copy"; }
    Truck(Truck&&) noexcept { last = "move"; }
};

Truck make() { return Truck{}; }
Truck make_named() {
    Truck t;
    return t;
}

void report(const char* code, const Truck&) {
    std::cout << code << "  ->  " << (last.empty() ? "elided" : last) << '\n';
    last.clear();
}

int main() {
    Truck a;
    const Truck spare{};
    { Truck t = a; report("Truck t = a;", t); }
    { Truck t = std::move(a); report("Truck t = std::move(a);", t); }
    { Truck t = make(); report("Truck t = make();", t); }
    { Truck t = Truck{}; report("Truck t = Truck{};", t); }
    { Truck t = make_named(); report("Truck t = make_named();", t); }
    { Truck t = std::move(spare); report("Truck t = std::move(spare);", t); }
}

