#include <iostream>
#include <mutex>

std::mutex lift;            // one key for the lift: one rider at a time
int rides = 0;

void ride(int floor) {
    std::scoped_lock key{lift};     // lock now; unlock at the closing brace
    if (floor < 0) {
        std::cout << "no floor " << floor << ", stepping out\n";
        return;
    }
    ++rides;
    std::cout << "ride to floor " << floor << '\n';
}

int main() {
    ride(4);
    ride(-1);
    ride(7);
    if (lift.try_lock()) {
        std::cout << "the lift is free again after " << rides << " rides\n";
        lift.unlock();
    }
}

