#include <cstdio>
#include <filesystem>
#include <iostream>

// Helper: how many files does this program still hold open?
// Linux lists them in /proc/self/fd. Four entries are always there:
// the keyboard, the screen, the error screen, and this listing itself.
int files_open() {
    std::filesystem::directory_iterator list{"/proc/self/fd"};
    int n = 0;
    for ([[maybe_unused]] const auto& entry : list) {
        ++n;
    }
    return n - 4;
}

bool save_score(const char* name, int score) {
    std::FILE* f = std::fopen(name, "w");
    if (f == nullptr) {
        return false;
    }
    if (score < 0) {
        std::cout << "bad score " << score << ", giving up\n";
        return false;
    }
    std::fprintf(f, "%d\n", score);
    std::fclose(f);
    return true;
}

int main() {
    save_score("ada.txt", 90);
    save_score("ben.txt", -5);
    save_score("cy.txt", -1);
    std::cout << "files still open: " << files_open() << '\n';
}

