#include <algorithm>
#include <iostream>
#include <utility>

class Truck {
public:
    explicit Truck(int boxes) : size_{boxes}, data_{new int[boxes]} {
        for (int i = 0; i < size_; ++i) data_[i] = i + 1;
        std::cout << "  load " << size_ << " new boxes\n";
    }
    Truck(const Truck& other) : size_{other.size_}, data_{new int[other.size_]} {
        std::copy(other.data_, other.data_ + size_, data_);
        std::cout << "  copy: pack " << size_ << " more boxes\n";
    }
    Truck(Truck&& other) noexcept : size_{other.size_}, data_{other.data_} {
        other.size_ = 0;
        other.data_ = nullptr;
        std::cout << "  move: hand over the keys\n";
    }
    Truck& operator=(const Truck&) = delete;    // assignment: panel 27
    Truck& operator=(Truck&&) = delete;
    ~Truck() {
        std::cout << "  unload " << size_ << " boxes\n";
        delete[] data_;
    }
    int size() const { return size_; }
private:
    int size_;
    int* data_;
};

int main() {
    Truck a{3};
    Truck b{a};
    Truck c{std::move(a)};
    std::cout << "a " << a.size() << ", b " << b.size() << ", c " << c.size() << '\n';
}

truck_assign.cpp.src:
#include <iostream>
#include <utility>

class Truck {
public:
    explicit Truck(int boxes) : size_{boxes}, data_{new int[boxes]{}} {
        std::cout << "  load " << size_ << " boxes\n";
    }
    Truck(Truck&& other) noexcept : size_{other.size_}, data_{other.data_} {
        other.size_ = 0;
        other.data_ = nullptr;
    }
    Truck& operator=(Truck&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = other.data_;
            other.size_ = 0;
            other.data_ = nullptr;
            std::cout << "  move-assign: old boxes out, new keys in\n";
        }
        return *this;
    }
    Truck(const Truck&) = delete;
    Truck& operator=(const Truck&) = delete;
    ~Truck() {
        std::cout << "  unload " << size_ << " boxes\n";
        delete[] data_;
    }
    int size() const { return size_; }
private:
    int size_;
    int* data_;
};

int main() {
    Truck a{3};
    Truck b{2};
    b = std::move(a);
    std::cout << "a " << a.size() << ", b " << b.size() << '\n';
    b = std::move(b);
    std::cout << "b " << b.size() << " after moving into itself\n";
}

vector_grow.cpp.src:
#include <iostream>
#include <vector>

int copies = 0;
int moves = 0;

struct Safe {                               // promises: my move never throws
    Safe() = default;
    Safe(const Safe&) { ++copies; }
    Safe(Safe&&) noexcept { ++moves; }
};

struct Unsure {                             // no promise
    Unsure() = default;
    Unsure(const Unsure&) { ++copies; }
    Unsure(Unsure&&) { ++moves; }
};

template <typename T>
void fill_three(const char* label, bool plan_ahead) {
    copies = 0;
    moves = 0;
    std::vector<T> v;
    if (plan_ahead) {
        v.reserve(3);
    }
    v.emplace_back();
    v.emplace_back();
    v.emplace_back();
    std::cout << label << ": " << copies << " copies, " << moves << " moves\n";
}

int main() {
    fill_three<Safe>("noexcept move          ", false);
    fill_three<Unsure>("move without noexcept  ", false);
    fill_three<Unsure>("no promise, reserve(3) ", true);
}
